`timescale 1ns/1ps
// Run from the package root; vectors generated by Python. Not yet executed here.
module tb_registration_axis;
    localparam W=5,H=4,N=W*H,FRAMES=6,OUT=N+4;
    reg clk=0; always #5 clk=~clk;
    reg rst_n=0;
    reg signed [31:0] a,b,c,d,e,f;
    reg [31:0] in_data=0; reg [3:0] in_keep=15;
    reg in_last=0,in_valid=0,out_ready=0;
    wire in_ready;
    wire [31:0] out_data; wire [3:0] out_keep;
    wire out_last,out_valid;
    reg [31:0] configs[0:FRAMES*6-1];
    reg [31:0] inputs[0:FRAMES*N-1];
    reg [31:0] expected[0:FRAMES*OUT-1];
    reg [31:0] lfsr=32'h12345678;
    integer received=0,frame_id,pixel_id,delay_id;
    reg stalled=0; reg [31:0] held_data; reg held_last;
    registration_axis #(.IMAGE_WIDTH(W),.IMAGE_HEIGHT(H)) dut(
        .clk(clk),.rst_n(rst_n),.a_in(a),.b_in(b),.c_in(c),.d_in(d),.e_in(e),.f_in(f),
        .s_axis_tdata(in_data),.s_axis_tkeep(in_keep),.s_axis_tlast(in_last),
        .s_axis_tvalid(in_valid),.s_axis_tready(in_ready),
        .m_axis_tdata(out_data),.m_axis_tkeep(out_keep),.m_axis_tlast(out_last),
        .m_axis_tvalid(out_valid),.m_axis_tready(out_ready));
    always @(negedge clk) begin
        if (!rst_n) out_ready<=0;
        else begin
            lfsr<={lfsr[30:0],lfsr[31]^lfsr[21]^lfsr[1]^lfsr[0]};
            out_ready<=lfsr[0]|lfsr[3];
        end
    end
    always @(posedge clk) if (rst_n) begin
        if (stalled && (!out_valid || out_data!==held_data || out_last!==held_last || out_keep!==4'hf))
            $fatal(1,"AXIS output changed under backpressure");
        stalled=out_valid&&!out_ready; held_data=out_data; held_last=out_last;
        if (out_valid&&out_ready) begin
            if (received>=FRAMES*OUT) $fatal(1,"Extra output word");
            if (out_data!==expected[received])
                $fatal(1,"Mismatch word %0d got %h expected %h",received,out_data,expected[received]);
            if (out_keep!==4'hf || out_last!==((received%OUT)==OUT-1))
                $fatal(1,"Bad TKEEP/TLAST at %0d",received);
            received=received+1;
        end
    end
    initial begin
        $readmemh("tests/vectors/config.mem",configs);
        $readmemh("tests/vectors/input.mem",inputs);
        $readmemh("tests/vectors/expected.mem",expected);
        repeat(4) @(negedge clk); rst_n=1;
        for(frame_id=0;frame_id<FRAMES;frame_id=frame_id+1) begin
            a=configs[frame_id*6]; b=configs[frame_id*6+1]; c=configs[frame_id*6+2];
            d=configs[frame_id*6+3]; e=configs[frame_id*6+4]; f=configs[frame_id*6+5];
            for(pixel_id=0;pixel_id<N;pixel_id=pixel_id+1) begin
                for(delay_id=0;delay_id<pixel_id%3;delay_id=delay_id+1) @(negedge clk);
                in_data=inputs[frame_id*N+pixel_id];
                in_keep=(frame_id==5&&pixel_id==3)?4'h7:4'hf;
                in_last=(pixel_id==N-1)||(frame_id==5&&pixel_id==3);
                in_valid=1;
                @(posedge clk); while(!in_ready) @(posedge clk);
                @(negedge clk); in_valid=0; in_last=0;
            end
            wait(received==(frame_id+1)*OUT);
            @(negedge clk);
        end
        repeat(10) @(negedge clk);
        if(received!=FRAMES*OUT) $fatal(1,"Wrong output count");
        $display("PASS: %0d frames, %0d words, fractional/negative/rotation/no-overlap, stalls, flags",FRAMES,received);
        $finish;
    end
    initial begin #1000000; $fatal(1,"Timeout"); end
endmodule
